import { useState } from "react";
function ShoppingItem({ item }) {
  return (
    <li>
      {item.text}
      <button className="remove-item btn-remove text-red">
        <i className="fa-solid fa-xmark"></i>
      </button>
    </li>
  );
}

export default ShoppingItem;
